import json, subprocess, sys, hashlib

BASE = 4
MAX_STEPS = 260
used = 0
found = False
visited = {}

def call(args):
    global used
    while True:
        p = subprocess.run([sys.executable, "avo_tool.py", *args], text=True, capture_output=True)
        if p.returncode == 0:
            if args[0] in ("probe", "reset"):
                used += 1
            return json.loads(p.stdout)
        if "acknowledgement" in (p.stdout+p.stderr).lower():
            subprocess.run([sys.executable, "avo_tool.py", "acknowledge_supervisor",
                            "Search now prunes unchanged states and switches action families rather than repeating inert probes."],
                           text=True, capture_output=True)
            continue
        raise RuntimeError(p.stdout+p.stderr)

def board(obs):
    return obs["payload"]["frame"][-1]

def key(obs, last):
    b = board(obs)
    players=[]
    for y,row in enumerate(b):
        for x,v in enumerate(row):
            if v in (2,8): players.append((x,y,v))
    # Preserve whether the marked target is still exposed.  Collapse cosmetic
    # surface-contact states 1/5/6 elsewhere.
    marks=[]
    for y,row in enumerate(b):
        for x,v in enumerate(row):
            if v in (3,4,7): marks.append((x,y,v))
    return (tuple(players), tuple(marks), obs["progress"]["levels_completed"], last)

ACTIONS=["ACTION1","ACTION3","ACTION2","ACTION5"]  # up,left,down,wait

def dfs(obs, path, maxdepth, last=""):
    global found
    if found or used >= MAX_STEPS: return False
    prog=obs["progress"]["levels_completed"]
    if prog>BASE or obs["status"] != "PLAYING":
        print("FOUND", path, prog, obs["status"], flush=True)
        found=True; return True
    if len(path)>=maxdepth: return False
    k=key(obs,last)
    if visited.get(k,999) <= len(path): return False
    visited[k]=len(path)
    before=json.dumps(board(obs),separators=(",",":"))
    for act in ACTIONS:
        if found or used>=MAX_STEPS: return found
        j=call(["probe",act,"--rationale","Systematic reversible search for a state-changing route to stomp the level target."])
        aft=j["transition"]["after"]
        after=json.dumps(board(aft),separators=(",",":"))
        # A single wait can alter hidden airborne timing despite an unchanged frame.
        changed=(after!=before) or act=="ACTION5"
        if changed and dfs(aft,path+[act],maxdepth,act): return True
        call(["probe","ACTION7","--rationale","Undo the explored branch to restore the exact parent state for reversible search."])
    return False

call(["reset","--reason","Controlled reversible search from the initial state of the current level."])
o=call(["observe"])["observation"]
for depth in range(4,13):
    visited.clear()
    print("DEPTH",depth,"used",used,flush=True)
    if dfs(o,[],depth): break
print("DONE found",found,"used",used,flush=True)

